  'help.yourEmail': 'Tavo el. paštas',
  'help.describe': 'Aprašyk problemą',
  'help.describePlaceholder': 'Papaskok, kas nutiko, su kuo daugiau detalių...',
  'help.send': 'Siųsti Pagalbą',
  'help.ticketSent': 'Pagalba Išsiųsta!',
  'help.ticketSentDesc': 'Gavome tavo užklausą. Mūsų komanda atsakys el. paštu per 24 valandas.',
  'help.close': 'Uždaryti',
  'help.ticketError': 'Nepavyko išsiųsti pagalbos. Bandyk dar kartą.',
  'help.type.cant_login': 'Negaliu prisijungti',
  'help.type.email_issue': 'Problema su el. paštu',
  'help.type.security': 'Saugumas',
  'help.type.other': 'Kita',
  'help.faq.cantLogin.q': 'Negaliu pasiekti savo paskyros',
  'help.faq.cantLogin.a': 'Patikrink, ar naudojiesi teisingu el. pašto adresu ir slaptažodžiu. Jei pamiršai slaptažodį, spausk "Pamiršai slaptažodį?" prisijungimo ekrane. Jei problema išlieka, sukurk pagalbos bilietą.',
  'help.faq.notReceiving.q': 'Negavau el. laiškų',
  'help.faq.notReceiving.a': 'Pirmiausia patikrink šlamšto aplanką. Įsitikink, kad tavo saugykla nėra pilna. Jei problema tęsiasi, patvirtink, kad siuntėjas turi teisingą adresą ir sukurk bilietą.',
  'help.faq.cantSend.q': 'Negaliu siųsti el. laiškų',
  'help.faq.cantSend.a': 'Patikrink savo interneto ryšį ir ar gavėjo adresas teisingas. Patikrink, ar priedai neviršija 25MB. Bandyk dar kartą po kelių minučių.',
  'help.faq.forgotPassword.q': 'Pamiršau savo slaptažodį',
  'help.faq.forgotPassword.a': 'Prisijungimo ekrane spausk "Pamiršai slaptažodį?" ir sek instrukcijas, kad atstatytum slaptažodį per atkūrimo el. paštą.',
  'help.faq.accountSecurity.q': 'Manau, kad mano paskyra buvo pažeista',
  'help.faq.accountSecurity.a': 'Nedelsiant pakeisk savo slaptažodį. Patikrink išsiųstų žinučių aplanką dėl žinučių, kurias nesisiuntei. Įjunk dviejų etapų autentifikavimą Nustatymuose > Saugumas. Jei reikia, sukurk skubų bilietą.',
  'help.faq.appAccess.q': 'Kaip pasiekti programėlę telefone?',
  'help.faq.appAccess.a': 'Tu gali pasiekti Chatyy per naršyklę adresu chatyy.com.br, arba atsisiųsti mūsų programėlę iš savo įrenginio programėlių parduotuvės.',
  'privacy.title': 'Privatumo Politika',
  'privacy.subtitle': 'Kaip saugome ir tvarkome tavo duomenis',
  'privacy.lastUpdated': 'Paskutinį kartą atnaujinta: Kovas 2026',
  'privacy.dataCollection.title': 'Duomenų Rinkimas',
  'privacy.dataCollection.body': 'Renkame tik būtiną informaciją el. pašto paslaugai: tavo vardą, el. pašto adresą ir žinučių, siunčiamų ir gaunamų, turinį. Neparduodame ir nesidalijame tavo asmeniniais duomenimis su trečiosiomis šalimis rinkodaros tikslais.',
  'privacy.dataUsage.title': 'Kaip Naudojame Tavo Duomenis',
  'privacy.dataUsage.body': 'Tavo duomenys naudojami tik el. pašto paslaugai teikti ir tobulinti, įskaitant žinučių pristatymą, šlamšto filtravimą, AI funkcijas (su tavo sutikimu) ir paskyros saugumą.',
  'privacy.dataSecurity.title': 'Duomenų Saugumas',
  'privacy.dataSecurity.body': 'Naudojame pramonės standartus atitinkančią šifravimą (TLS/SSL) visiems duomenims, kurie perduodami ir saugomi. Sesijos yra apsaugotos šifruotais ženklais ir CSRF apsauga. Reguliariai tikriname savo saugumo praktiką.',
  'privacy.cookies.title': 'Slapukai ir Vietinė Saugykla',
  'privacy.cookies.body': 'Naudojame būtinus slapukus ir vietinę saugyklą, kad išlaikytume tavo sesiją, prisimintume tavo pageidavimus (tema, kalba) ir suteiktume sklandžią patirtį. Nenaudojame trečiųjų šalių sekimo slapukų.',
  'privacy.thirdParties.title': 'Trečiųjų Šalių Paslaugos',
  'privacy.thirdParties.body': 'Galime naudoti trečiųjų šalių paslaugas specifinėms funkcijoms, tokioms kaip AI (Anthropic Claude) ir pranešimų siuntimas. Šios paslaugos laikosi savo privatumo politikos ir apdoroja tik minimalų būtiną duomenų kiekį.',
  'privacy.rights.title': 'Tavo Teisės',
  'privacy.rights.body': 'Tu turi teisę bet kada pasiekti, taisyti, eksportuoti ar ištrinti savo asmeninius duomenis. Tu gali valdyti savo duomenis Nustatymuose arba susisiekdamas su mūsų palaikymo komanda.',
  'privacy.contact.title': 'Susisiek Su Mumis',
  'privacy.contact.body': 'Dėl privatumo klausimų ar duomenų užklausų, susisiek su privacy@chatyy.com.br. Atsakysime per 30 dienų.',
  'terms.title': 'Paslaugų Sąlygos',
  'terms.subtitle': 'Chatyy naudojimo gairės',
  'terms.lastUpdated': 'Paskutinį kartą atnaujinta: Kovas 2026',
  'terms.acceptance.title': 'Sąlygų Priėmimas',
  'terms.acceptance.body': 'Pasiekdamas arba naudodamas Chatyy, tu sutinki su šiomis Paslaugų Sąlygomis. Jei nesutinki su bet kuria šių sąlygų dalimi, nenaudok paslaugos.',
  'terms.services.title': 'Paslaugų Aprašymas',
  'terms.services.body': 'Chatyy teikia el. pašto komunikacijos paslaugas, įskaitant el. laiškų siuntimą, gavimą ir valdymą, taip pat AI funkcijas, integraciją su kalendoriumi ir vaizdo konferencijomis.',
  'terms.accounts.title': 'Vartotojo Paskyros',
  'terms.accounts.body': 'Tu esi atsakingas už savo prisijungimo duomenų saugumą. Neatskleisk savo slaptažodžio ir neleisk neautorizuotam asmeniui pasiekti savo paskyros. Tu turi būti bent 13 metų, kad galėtum naudotis šia paslauga.',
  'terms.conduct.title': 'Priimtinas Naudojimas',
  'terms.conduct.body': 'Tu sutinki nenaudoti paslaugos siųsti šlamšto, kenkėjiškų programų, phishing ar bet kokio neteisėto turinio. Nebandyk pasiekti kitų vartotojų paskyrų ar trikdyti paslaugos infrastruktūros.',
  'terms.content.title': 'Turinio Nuosavybė',
  'terms.content.body': 'Tu išlaikai nuosavybę viso turinio, kurį kuri ir siunči per paslaugą. Mes nepretenduojame į tavo el. laiškus ar priedus. Galime apdoroti turinį, kaip reikia, kad suteiktume paslaugą.',
  'terms.limitation.title': 'Atsakomybės Apribojimas',
  'terms.limitation.body': 'Chatyy teikiama "kaip yra". Siekiame 99,9% prieinamumo, bet negarantuojame nenutrūkstamos paslaugos. Mes nesame atsakingi už netiesioginius, atsitiktinius ar pasekminius nuostolius, atsirandančius naudojantis paslauga.',
  'terms.termination.title': 'Paskyros Uždarymas',
  'terms.termination.body': 'Galime sustabdyti arba uždaryti paskyras, kurios pažeidžia šias sąlygas. Tu gali ištrinti savo paskyrą bet kada Nustatymuose. Po uždarymo tavo duomenys bus ištrinti per 30 dienų.',
  'terms.changes.title': 'Sąlygų Pakeitimai',
  'terms.changes.body': 'Galime periodiškai atnaujinti šias sąlygas. Apie reikšmingus pakeitimus pranešime el. paštu arba pranešimu programėlėje. Tęsiant naudojimą po pakeitimų, laikoma, kad sutinki su atnaujintomis sąlygomis.',
